import {createGameScene} from './game-scene.js';
import {mountTraining} from './training.js';
import {renderReceiver} from './receiver.js';
import {missions,introSteps,fieldGuide} from './story.js';
import {createExperiment,runComparison,sources,modelNote,modelDetails} from './science.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const randomSeed=()=>crypto.getRandomValues(new Uint32Array(1))[0];
const letters=['A','B','C'];
const state={phase:'intro',level:0,selectedZone:0,targetZone:0,referenceReady:false,clues:[],energy:12,used:0,paused:false,sound:false,revealed:false,alignmentStart:0,alignmentPosition:.5,results:[],log:[],introStep:0,flightZone:0,lastReading:null};
let audioContext=null,toastTimer=null,flightFallback=null,flightTextTimer=null,markerFrame=null,lastFrame=0,modalFocus=null,modalPaused=false,modalSessionActive=false;
const engine=createGameScene($('#game-world'),event=>{if(state.paused)return;if(event.type==='zone'&&state.phase==='aim'){selectZone(event.zone);}if(event.type==='reference'&&state.phase==='prepare'){prepareReference();}if(event.type==='returned'&&state.phase==='observe'){beginAlignment();}});
let trainingInstance=null,trainingActive=false;
const mission=()=>missions[state.level];
function sync(){engine.setState({phase:state.phase,selectedZone:state.selectedZone,noise:state.phase==='intro'?.2:mission().noise,referenceReady:state.referenceReady,clues:state.clues.length?state.clues:[0,1,2].map(()=>({samples:0,score:0})),revealed:state.revealed,targetZone:state.targetZone,level:state.level+1,running:state.phase==='observe',receiverActive:state.phase==='align'});$('#energy').textContent=state.energy;$('#level-number').textContent=String(state.level+1).padStart(2,'0');$('#level-name').textContent=mission().title.split(' · ')[1];}
function beep(kind='tap'){if(!state.sound)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();const t=audioContext.currentTime;const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type=kind==='win'?'sine':'triangle';osc.frequency.setValueAtTime(kind==='launch'?330:kind==='catch'?620:kind==='win'?780:400,t);osc.frequency.exponentialRampToValueAtTime(kind==='launch'?820:kind==='win'?1200:500,t+.16);gain.gain.setValueAtTime(.035,t);gain.gain.exponentialRampToValueAtTime(.001,t+.24);osc.connect(gain).connect(audioContext.destination);osc.start(t);osc.stop(t+.25);}catch{}}
function notify(text){$('#scene-toast').textContent=text;$('#scene-toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#scene-toast').classList.remove('visible'),3700);}
function flightText(text){$('#flight-label').textContent=text;$('#flight-label').classList.toggle('show',!!text);}
function beginLevel(level=0){clearFlight();state.level=level;state.phase='prepare';state.selectedZone=0;state.targetZone=randomSeed()%3;state.referenceReady=false;state.revealed=false;state.energy=mission().budget;state.used=0;state.clues=[0,1,2].map(()=>({samples:0,score:0}));state.log=[];state.lastReading=null;state.introStep=0;state.paused=false;$('.pause-overlay')?.remove();engine.setPaused(false);$('#intro-copy').hidden=true;$('#start-footer').hidden=true;$('#game-console').hidden=false;$('#game-hud').hidden=false;$('#receiver-panel').hidden=false;$('.game-shell').classList.add('playing');renderConsole();sync();notify(mission().brief);beep();}
function prepareReference(){if(state.phase!=='prepare'||state.paused)return;state.referenceReady=true;state.phase='aim';engine.prepareSource?.();sync();renderConsole();notify('小探和小参出场！小探去找目标，小参留在家里。');beep('catch');}
function selectZone(zone){if(state.phase!=='aim'||state.paused)return;state.selectedZone=zone;sync();renderConsole();beep();}
function launch(){if(state.phase!=='aim'||!state.referenceReady||state.energy<=0||state.paused)return;state.phase='observe';state.energy--;state.used++;state.flightZone=state.selectedZone;state.introStep=1;sync();renderConsole();flightText(`新的一对准备好了！小探飞向 ${letters[state.selectedZone]} 区，小参留守`);engine.launch(state.selectedZone);beep('launch');flightTextTimer=setTimeout(()=>{if(state.phase==='observe')flightText('沙沙沙……收到的东西里，可能藏着一点回声。');},1400);flightFallback=setTimeout(()=>{if(state.phase==='observe'&&!state.paused)beginAlignment();},5000);}
function clearFlight(){clearTimeout(flightFallback);clearTimeout(flightTextTimer);flightText('');if(markerFrame){cancelAnimationFrame(markerFrame);markerFrame=null;}}
function beginAlignment(){if(state.phase!=='observe')return;clearTimeout(flightFallback);clearTimeout(flightTextTimer);state.phase='align';state.introStep=2;state.alignmentStart=performance.now();lastFrame=performance.now();renderConsole();sync();flightText('回来的信号好吵！让留下的小参也来帮忙。');tickMarker(performance.now());}
function tickMarker(t){if(state.phase!=='align'){markerFrame=null;return;}if(state.paused)state.alignmentStart+=t-lastFrame;lastFrame=t;const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;state.alignmentPosition=reduced?.5:.5-.47*Math.cos((t-state.alignmentStart)/1000*Math.PI*1.15);const marker=$('#timing-marker');if(marker)marker.style.left=state.alignmentPosition*100+'%';markerFrame=requestAnimationFrame(tickMarker);}
function catchEcho(){if(state.phase!=='align'||state.paused)return;const alignment=.55+.45*(1-Math.min(1,Math.abs(state.alignmentPosition-.5)/.47));const zone=state.flightZone;const exp=createExperiment({noise:mission().noise,retention:mission().retention,alignment,mode:'quantum',targetPresent:zone===state.targetZone,seed:randomSeed()});const sample=exp.sample(16);state.lastReading={zone,llr:sample.llr,readings:sample.readings};state.clues[zone].samples+=16;state.clues[zone].score+=sample.llr;state.log.push({zone,alignment,llr:sample.llr});state.phase='aim';cancelAnimationFrame(markerFrame);markerFrame=null;flightText('');sync();renderConsole();beep('catch');const quality=alignment>.93?'接得很准！':alignment>.76?'接住了。':'接偏了一点。';notify(`${quality}${letters[zone]} 区新增一组线索：${clueLabel(zone)}。${state.energy===0?'探测次数用完了，选择最可疑的区域吧。':'可以换个区域，也可以再探一次。'}`);}
function clueLabel(i){const c=state.clues[i];if(!c?.samples)return '还没有线索';if(c.score>3)return '回声很可疑';if(c.score>1)return '有一些动静';if(c.score< -2)return '暂时没发现';return '还拿不准';}
function zones(){return `<div class="zones" role="group" aria-label="选择探测区域">${state.clues.map((c,i)=>`<button class="zone-button ${i===state.selectedZone?'selected':''}" data-zone="${i}" aria-pressed="${i===state.selectedZone}"><strong>${letters[i]}</strong><div><span>${clueLabel(i)}</span><small>${c.samples?'已探测 '+c.samples/16+' 次':'点击选择'}</small></div></button>`).join('')}</div>`;}
function coach(title,line,tag){return `<div class="coach-line"><div class="coach-avatar" aria-hidden="true"></div><div class="coach-content"><strong>${title}</strong><p>${line}</p>${tag?`<span class="learn-tag">✦ ${tag}</span>`:''}<div class="progress-mini" aria-label="雷达流程：准备、发射、联合接收"><span class="${state.referenceReady?'done':''}"></span><span class="${state.introStep>=1?'done':''}"></span><span class="${state.introStep>=2?'done':''}"></span></div></div></div>`;}
function renderConsole(){let html='';if(state.phase==='prepare')html=coach('叫醒两位光伙伴。','纠缠源一起准备小探和小参。小探去接触目标，小参保存在本地，等回波回来。','这只光盒叫“纠缠源”。每次探测，都要准备新的一对。')+`<div class="console-actions"><button class="big-action violet" id="prepare-button">叫醒小探和小参 <span>→</span></button><p class="empty-guide">一束出发，一束留下。</p></div>`;if(state.phase==='aim'){const c=state.clues[state.selectedZone];html=coach(state.used===0?'选个区域，让雷达去看看。':state.energy===0?'最后的判断，交给你了。':'接下来，你想探测哪里？',state.used===0?'三个区域中只有一个藏着目标。点选 A、B 或 C，然后发射一束探测信号。':state.energy===0?'比较三个区域的线索，选中最可疑的一个，再锁定目标。':'有动静不一定就是目标。再探一次，或者换个区域看看。','小参在家等。它自己可不知道目标在哪儿。')+`<div class="console-actions">${zones()}<div class="console-dual"><button class="big-action" id="launch-button" ${state.energy<=0?'disabled':''}>发射 → ${letters[state.selectedZone]} 区 <span>⚡</span></button><button class="big-action ${state.energy===0?'coral':'light'}" id="lock-button" ${!state.used?'disabled':''}>锁定这里 ◎</button></div><span class="keyboard-hint">空格发射 · 方向键选择区域</span></div>`;}if(state.phase==='observe')html=coach('回声很小，周围又很吵。','这里如果藏着目标，就可能收到一点回声；空区域也会传来杂乱的噪声。','这些捣乱的信号叫“噪声”。空区域也会有。')+`<div class="console-actions"><button class="big-action" disabled>正在听 ${letters[state.flightZone]} 区的动静…</button><p class="empty-guide">小探出门，小参一直留在家。</p></div>`;if(state.phase==='align')html=coach('两路一起看，找出一点线索。','等紫色小点走进绿色窗口，按“一起检查”。雷达会把收到的信号和小参放在一起检查。','回波带来目标作用的信息，小参提供参考。两路一起测量，噪声仍然会捣乱。')+`<div class="console-actions"><div class="timing-wrap"><div class="timing-labels"><span>还没到</span><span>在这里碰面</span><span>已错过</span></div><div class="timing-meter" aria-label="紫色小点走到绿色窗口时按下一起检查"><span class="timing-target"></span><span class="timing-center"></span><span class="timing-marker" id="timing-marker"></span></div></div><button class="big-action violet" id="catch-button">一起检查 ✦</button><span class="keyboard-hint">点击按钮或按空格 · 可以等下一次经过窗口</span></div>`;if(state.phase==='reveal')html=coach('探测完成，目标揭晓。',`目标藏在 ${letters[state.targetZone]} 区。你让一束光出发、一束光留下，又从吵闹的信号里收集了线索。`,'猜对一次还不够，多试几次才更可靠。')+`<div class="console-actions"><button class="big-action" id="review-button">查看这一关的发现 →</button></div>`;$('#game-console').innerHTML=html;$('#prepare-button')?.addEventListener('click',prepareReference);$('#launch-button')?.addEventListener('click',launch);$('#catch-button')?.addEventListener('click',catchEcho);$('#lock-button')?.addEventListener('click',lockTarget);$$('[data-zone]').forEach(b=>b.addEventListener('click',()=>selectZone(+b.dataset.zone)));$('#review-button')?.addEventListener('click',showResult);renderReceiver($('#receiver-panel'),{...state,noise:mission().noise,letters,selectedZone:state.phase==='align'||state.phase==='observe'?state.flightZone:state.selectedZone});$('#revisit-training').onclick=()=>beginTraining(false);}
function lockTarget(){if(state.phase!=='aim'||!state.used||state.paused)return;state.phase='reveal';state.revealed=true;const win=state.selectedZone===state.targetZone;const stars=win?(state.used<=6?3:state.used<=9?2:1):0;state.results[state.level]={win,stars,used:state.used,guess:state.selectedZone,target:state.targetZone};sync();renderConsole();beep(win?'win':'tap');notify(win?'找到了！量子雷达的线索帮你找到了目标。':`目标其实在 ${letters[state.targetZone]} 区。这一次，噪声藏住了线索。`);setTimeout(()=>{if(state.phase==='reveal'&&!$('#game-modal').open)showResult();},800);}
function showResult(){const r=state.results[state.level];showModal(`<div class="modal-eyebrow">第 ${state.level+1} 关 · 探测报告</div><div class="result-stars" aria-label="${r.stars}颗星">${[0,1,2].map(i=>`<span class="${i<r.stars?'':'off'}">★</span>`).join('')}</div><h2>${r.win?'目标找到了！':'噪声，也会开玩笑。'}</h2><p>${r.win?mission().winLine:`你选择了 ${letters[r.guess]} 区，目标实际在 ${letters[r.target]} 区。再多一点证据，也许会改变判断。`}</p><div class="result-metrics"><div><small>使用探测次数</small><strong>${r.used}<small> / ${mission().budget}</small></strong></div><div><small>目标所在区域</small><strong>${letters[r.target]}</strong></div></div><div class="discovery"><strong>这一关，你发现了</strong><p>${mission().lesson}</p></div><div class="modal-actions"><button class="big-action light" id="retry-level">再试一次</button><button class="big-action" id="next-level">${state.level<2?'下一关 →':'完成旅程 →'}</button></div>`);$('#retry-level').onclick=()=>{closeModal();beginLevel(state.level);};$('#next-level').onclick=()=>{closeModal();if(state.level<2)beginLevel(state.level+1);else showFinal();};}
function showFinal(){const total=state.results.reduce((n,r)=>n+(r?.stars||0),0);const wins=state.results.filter(r=>r?.win).length;showModal(`<div class="modal-eyebrow">回声侦探 · 三关旅程完成</div><div class="result-stars">✦ ✦ ✦</div><h2>你的量子雷达，<br/>完成了第一次寻踪。</h2><p>你找对了 ${wins} 个目标，收集 ${total} / 9 颗星。更重要的是，你看见了量子照明的一整条探测过程。</p><div class="help-steps">${introSteps.map((s,i)=>`<div class="help-step"><b>${i+1}</b><div><strong>${s.action}</strong><p>${s.line}</p></div></div>`).join('')}</div><div class="discovery"><strong>再多问一步</strong><p>留下的小参要保存好，雷达也要用对检查方法。两束光的配合才更有用。</p></div><div class="modal-actions"><button class="big-action light" id="compare-final">好奇的话，再看一点</button><button class="big-action" id="replay-final">再玩一轮 →</button></div>`);$('#replay-final').onclick=()=>{closeModal();state.results=[];beginLevel(0);};$('#compare-final').onclick=()=>{closeModal();showComparison();};}
function showComparison(){const comparisonSeed=randomSeed();const result=runComparison({noise:.6,retention:1,alignment:1,trials:400,samples:24,seed:comparisonSeed});showModal(`<div class="modal-eyebrow">小小对照实验</div><h2>它的帮助，要多试几次看。</h2><p>在相同背景和采样预算下，两种教学方案各做 400 次“有或无目标”的判断。一次输赢不能说明整体表现。</p><div class="result-metrics"><div><small>量子教学方案 · 正确判断</small><strong>${result.quantum.correct}<small> / 400</small></strong></div><div><small>经典教学方案 · 正确判断</small><strong>${result.classical.correct}<small> / 400</small></strong></div></div><div class="discovery"><strong>优势有条件</strong><p>这里使用任意参数的教学模型，数字不代表真实雷达性能。实际比较还需要严格统一发射资源与接收条件。</p></div><button class="big-action" id="compare-poor">如果参考没保存好呢？ →</button>`);$('#compare-poor').onclick=()=>{const poor=runComparison({noise:.6,retention:.05,alignment:1,trials:400,samples:24,seed:comparisonSeed});$('.result-metrics').innerHTML=`<div><small>参考损失后 · 量子教学方案</small><strong>${poor.quantum.correct}<small> / 400</small></strong></div><div><small>经典教学方案</small><strong>${poor.classical.correct}<small> / 400</small></strong></div>`;$('.discovery p').textContent='这组教学条件下，参考保存不足会降低量子方案的表现。制备、保存和接收共同决定效果；这里的数字只用于说明这种关系。';$('#compare-poor').textContent='明白了，回到雷达';$('#compare-poor').onclick=closeModal;};}
function showModal(html){
  if(!modalSessionActive){modalFocus=document.activeElement;modalPaused=state.paused;modalSessionActive=true;}
  state.paused=true;engine.setPaused(true);
  $('#modal-body').innerHTML=html;
  if(!$('#game-modal').open)$('#game-modal').showModal();
  $('#game-modal').scrollTop=0;
}
function restoreModalState(){
  if(!modalSessionActive||$('#game-modal').open)return;
  modalSessionActive=false;
  if(!modalPaused&&!trainingActive){state.paused=false;engine.setPaused(false);if(state.phase==='observe'){clearTimeout(flightFallback);flightFallback=setTimeout(()=>{if(state.phase==='observe'&&!state.paused)beginAlignment();},5000);}}
  if(modalFocus?.isConnected)modalFocus.focus({preventScroll:true});
}
function closeModal(){$('#game-modal').close();restoreModalState();}
$('#game-modal').addEventListener('close',restoreModalState);
function showHelp(){showModal(`<div class="modal-eyebrow">一分钟上手</div><h2>你是这台雷达的指挥官。</h2><p>三个区域里，只有一个藏着目标。每关有 12 次探测机会，找到它就赢。</p><div class="help-steps"><div class="help-step"><b>1</b><div><strong>叫醒伙伴，选择区域</strong><p>先和两束光玩一下，再体验参考怎样帮忙。正式任务里，准备好两路信号，再点 A、B 或 C。</p></div></div><div class="help-step"><b>2</b><div><strong>发射，然后接住回波</strong><p>看信号飞出去再回来。紫色光点到绿色窗口时，点击“一起检查”。</p></div></div><div class="help-step"><b>3</b><div><strong>多找线索，再锁定目标</strong><p>比较三个区域的动静。拿不准就再探一次，有把握再锁定。</p></div></div></div><p>电脑可用方向键选择、空格发射或接收。每次有效探测会消耗一次机会。三星需要在 6 次内找对，9 次内找对获得两星，其余正确判断获得一星。</p><button class="big-action" id="help-done">知道了，开始试试 →</button>`);$('#help-done').onclick=closeModal;}
function showGuide(){showModal(`<div class="modal-eyebrow">从游戏里，带走一点科学</div><h2>回声侦探的发现手册</h2>${fieldGuide.map(g=>`<details class="guide-details"><summary>${g.question}</summary><p>${g.answer}</p></details>`).join('')}<p>绿紫伙伴和“沙沙声”是讲故事用的比喻。真正的微波看不见，也不是声音。</p><button class="mini-action" id="open-lab">进入完整八步实验台 ↗</button>`);$('#open-lab').onclick=()=>{window.location.href='./lab.html';};}
function showSources(){showModal(`<div class="modal-eyebrow">科学依据与原创说明</div><h2>游戏背后的量子照明</h2><p>雷达发出探测信号照射目标区域，并收集回波；量子照明方案在源头准备具有量子纠缠的探测与参考模式，把参考保留在本地，与返回信号进行合适的联合测量。</p><div class="discovery"><strong>怎样理解游戏里的结果</strong><p>三岛寻踪游戏与八步实验台：${modelNote}</p><p>开场第三幕另用理想相位共轭接收器模型，演示两路干涉、出口光子计数及差值累积。假设与参数见该幕的“数字从哪里来”。</p></div><details class="guide-details"><summary>查看教学模型与游戏规则</summary><p>${modelDetails}</p><p>本游戏将三个已设定区域组成一道寻找任务，恰有一处含目标。每次发射获得16个教学样本；匹配程度由时机操作映射至0.55—1.00。各区域累加对应批次的对数似然比，玩家比较它们后选择目标。线索描述不等于目标概率；场景里的迷雾是背景噪声的可视化比喻。每次生成新信号，参考不会跨探测重复使用。星级反映个人游戏表现。</p></details><details class="guide-details"><summary>光源关系视图与联合测量</summary><p>开场是教学透视，不执行真实测量。角色和光带表示两路之间的关系，没有预写答案，也不是可传信的连接。源头关联条采用理想双模压缩真空态：两路平均光子数均为N=0.05，相位敏感关联参数Cq=2√[N(N+1)]；与该源逐路平均光子数相同的经典态上限Cc=2N。条长表示该特定关联，不是探测成功率，也不是光子对的轨迹或实测数据。该关系视图不能用于验证纠缠。</p><p>接收幕逐步展示相位共轭处理、两路在分束器中干涉、两个出口探测和计数差累积。每组使用1024对全新模式，理想参考无损保存，传播相位稳定且已补偿。计数模型包括相位共轭必需的真空噪声。更换参考时保留各路平均亮度，换用另一独立模式并重新抽样。此对照说明关联怎样被读出；它没有比较最佳经典探测策略，不能单独验证量子优势。</p></details>${sources.map(s=>`<div class="source"><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title} ↗</a><p>${s.note}</p></div>`).join('')}<p>使用 Game Studio 工作流与 Phaser 游戏引擎。场景、角色、雷达装置、界面和合成音效均为本项目原创制作；没有使用论文插图。正式参赛的公开刊发及相应证明需另行落实。</p>`);}
function pauseGame(){if(state.phase==='intro')return;if(state.paused)return;state.paused=true;engine.setPaused(true);const overlay=document.createElement('div');overlay.className='pause-overlay';overlay.innerHTML='<h2>休息一下，回声会等你。</h2><button class="big-action" id="resume-game">继续探测 →</button>';$('.game-board').append(overlay);$('#resume-game').onclick=()=>{overlay.remove();state.paused=false;engine.setPaused(false);if(state.phase==='observe'){clearTimeout(flightFallback);flightFallback=setTimeout(()=>{if(state.phase==='observe'&&!state.paused)beginAlignment();},5000);}};}
function beginTraining(startNew=false){
  if(trainingActive)return;
  const previousPaused=state.paused;
  const hiddenElements=[$('#game-console'),$('#receiver-panel'),$('#start-footer')].map(element=>({element,hidden:element.hidden}));
  trainingActive=true;state.paused=true;engine.setPaused(true);$('.game-board').inert=true;
  hiddenElements.forEach(({element})=>element.hidden=true);
  $('#training-section').hidden=false;
  $('.game-shell').classList.add('training-active');
  const leaveTraining=(completed=false)=>{
    trainingInstance?.destroy();trainingInstance=null;trainingActive=false;
    $('#training-section').hidden=true;$('.game-shell').classList.remove('training-active');$('.game-board').inert=false;
    hiddenElements.forEach(({element,hidden})=>element.hidden=hidden);
    state.paused=previousPaused;engine.setPaused(previousPaused);
    if(startNew&&completed){beginLevel(0);$('#prepare-button')?.focus({preventScroll:true});}
    else if(state.phase==='observe'&&!state.paused){clearTimeout(flightFallback);flightFallback=setTimeout(()=>{if(state.phase==='observe'&&!state.paused)beginAlignment();},5000);}
    $('.game-shell').scrollIntoView({block:'start',behavior:'instant'});
  };
  trainingInstance=mountTraining($('#training-section'),{onSound:()=>beep('catch'),onComplete:()=>leaveTraining(true),onExit:()=>leaveTraining(false)});
  $('#training-section button:not(:disabled)')?.focus({preventScroll:true});
  $('.game-shell').scrollIntoView({block:'start',behavior:'instant'});
}
$('#start-button').onclick=()=>beginTraining(true);
$('#training-button').onclick=()=>beginTraining(false);
$('#sound-toggle').onclick=()=>{state.sound=!state.sound;$('#sound-toggle span').textContent=state.sound?'声音开':'静音';$('#sound-toggle').setAttribute('aria-label',state.sound?'关闭游戏声音':'开启游戏声音');beep();};
$('#help-button').onclick=showHelp;$('#science-button').onclick=showGuide;$('#guide-button').onclick=showGuide;$('#sources-button').onclick=showSources;$('#pause-button').onclick=pauseGame;$('#modal-close').onclick=closeModal;
$('#game-modal').addEventListener('click',e=>{if(e.target===$('#game-modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
document.addEventListener('keydown',e=>{if($('#game-modal').open||state.paused||e.repeat)return;if(e.code==='Space'&&!['BUTTON','INPUT','SUMMARY','A'].includes(document.activeElement?.tagName)){e.preventDefault();if(state.phase==='prepare')prepareReference();else if(state.phase==='aim')launch();else if(state.phase==='align')catchEcho();}if(state.phase==='aim'&&(e.code==='ArrowLeft'||e.code==='ArrowRight')){e.preventDefault();selectZone((state.selectedZone+(e.code==='ArrowLeft'?2:1))%3);}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.phase!=='intro'&&state.phase!=='reveal'&&!state.paused&&!$('#game-modal').open)pauseGame();});
sync();
